
-- Modulo 51: Facturacion Electronica

CREATE TABLE "Facturas" (
                            "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
                            "ClienteId" integer NOT NULL,
                            "OrdenCompraId" integer,
                            "TipoComprobante" character varying(20) NOT NULL,
                            "Serie" character varying(10) NOT NULL,
                            "Numero" integer NOT NULL,
                            "FechaEmision" timestamp with time zone NOT NULL,
                            "FechaVencimiento" timestamp with time zone,
                            "Moneda" character varying(3) NOT NULL,
                            "Estado" character varying(20) NOT NULL DEFAULT 'Borrador',
                            "Subtotal" numeric(18,2) NOT NULL DEFAULT 0,
                            "TotalDescuento" numeric(18,2) NOT NULL DEFAULT 0,
                            "TotalImpuesto" numeric(18,2) NOT NULL DEFAULT 0,
                            "Total" numeric(18,2) NOT NULL DEFAULT 0,
                            "Observaciones" character varying(500),
                            "FechaCreacion" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                            "FechaAnulacion" timestamp with time zone,
                            "MotivoAnulacion" character varying(500),

                            CONSTRAINT "PK_Facturas"
                                PRIMARY KEY ("Id"),

                            CONSTRAINT "FK_Facturas_Clientes_ClienteId"
                                FOREIGN KEY ("ClienteId")
                                    REFERENCES "Clientes" ("Id")
                                    ON DELETE RESTRICT,

                            CONSTRAINT "FK_Facturas_OrdenesCompra_OrdenCompraId"
                                FOREIGN KEY ("OrdenCompraId")
                                    REFERENCES "OrdenesCompra" ("Id")
                                    ON DELETE RESTRICT,

                            CONSTRAINT "CK_Facturas_TipoComprobante"
                                CHECK ("TipoComprobante" IN ('Factura', 'Boleta')),

                            CONSTRAINT "CK_Facturas_Numero"
                                CHECK ("Numero" > 0),

                            CONSTRAINT "CK_Facturas_Serie"
                                CHECK (length(trim("Serie")) > 0),

                            CONSTRAINT "CK_Facturas_Moneda"
                                CHECK ("Moneda" ~ '^[A-Z]{3}$'),

    CONSTRAINT "CK_Facturas_Estado"
        CHECK (
            "Estado" IN (
                'Borrador',
                'Emitida',
                'Anulada'
            )
        ),

    CONSTRAINT "CK_Facturas_FechaVencimiento"
        CHECK (
            "FechaVencimiento" IS NULL
            OR "FechaVencimiento" >= "FechaEmision"
        ),

    CONSTRAINT "CK_Facturas_Importes"
        CHECK (
            "Subtotal" >= 0
            AND "TotalDescuento" >= 0
            AND "TotalDescuento" <= "Subtotal"
            AND "TotalImpuesto" >= 0
            AND "Total" >= 0
        ),

    CONSTRAINT "CK_Facturas_Total"
        CHECK (
            "Total" =
            "Subtotal" - "TotalDescuento" + "TotalImpuesto"
        ),

    CONSTRAINT "CK_Facturas_Anulacion"
        CHECK (
            (
                "Estado" = 'Anulada'
                AND "FechaAnulacion" IS NOT NULL
                AND "MotivoAnulacion" IS NOT NULL
                AND length(trim("MotivoAnulacion")) > 0
            )
            OR
            (
                "Estado" <> 'Anulada'
                AND "FechaAnulacion" IS NULL
                AND "MotivoAnulacion" IS NULL
            )
        )
);

CREATE UNIQUE INDEX "IX_Facturas_TipoComprobante_Serie_Numero"
    ON "Facturas" (
                   "TipoComprobante",
                   "Serie",
                   "Numero"
        );

CREATE INDEX "IX_Facturas_ClienteId"
    ON "Facturas" ("ClienteId");

CREATE INDEX "IX_Facturas_OrdenCompraId"
    ON "Facturas" ("OrdenCompraId");

CREATE INDEX "IX_Facturas_FechaEmision"
    ON "Facturas" ("FechaEmision");

CREATE INDEX "IX_Facturas_Estado"
    ON "Facturas" ("Estado");


CREATE TABLE "DetallesFactura" (
                                   "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
                                   "FacturaId" integer NOT NULL,
                                   "ProductoId" integer NOT NULL,
                                   "ImpuestoId" integer,
                                   "Descripcion" character varying(300) NOT NULL,
                                   "Cantidad" numeric(18,4) NOT NULL,
                                   "PrecioUnitario" numeric(18,2) NOT NULL,
                                   "DescuentoPorcentaje" numeric(5,2) NOT NULL DEFAULT 0,
                                   "PorcentajeImpuesto" numeric(18,6) NOT NULL DEFAULT 0,
                                   "Subtotal" numeric(18,2) NOT NULL,
                                   "ImporteDescuento" numeric(18,2) NOT NULL DEFAULT 0,
                                   "BaseImponible" numeric(18,2) NOT NULL,
                                   "ImporteImpuesto" numeric(18,2) NOT NULL DEFAULT 0,
                                   "Total" numeric(18,2) NOT NULL,

                                   CONSTRAINT "PK_DetallesFactura"
                                       PRIMARY KEY ("Id"),

                                   CONSTRAINT "FK_DetallesFactura_Facturas_FacturaId"
                                       FOREIGN KEY ("FacturaId")
                                           REFERENCES "Facturas" ("Id")
                                           ON DELETE RESTRICT,

                                   CONSTRAINT "FK_DetallesFactura_Productos_ProductoId"
                                       FOREIGN KEY ("ProductoId")
                                           REFERENCES "Productos" ("Id")
                                           ON DELETE RESTRICT,

                                   CONSTRAINT "FK_DetallesFactura_Impuestos_ImpuestoId"
                                       FOREIGN KEY ("ImpuestoId")
                                           REFERENCES "Impuestos" ("Id")
                                           ON DELETE RESTRICT,

                                   CONSTRAINT "CK_DetallesFactura_Cantidad"
                                       CHECK ("Cantidad" > 0),

                                   CONSTRAINT "CK_DetallesFactura_PrecioUnitario"
                                       CHECK ("PrecioUnitario" >= 0),

                                   CONSTRAINT "CK_DetallesFactura_DescuentoPorcentaje"
                                       CHECK (
                                           "DescuentoPorcentaje" >= 0
                                               AND "DescuentoPorcentaje" <= 100
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_PorcentajeImpuesto"
                                       CHECK (
                                           "PorcentajeImpuesto" >= 0
                                               AND "PorcentajeImpuesto" <= 100
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_Importes"
                                       CHECK (
                                           "Subtotal" >= 0
                                               AND "ImporteDescuento" >= 0
                                               AND "ImporteDescuento" <= "Subtotal"
                                               AND "BaseImponible" >= 0
                                               AND "ImporteImpuesto" >= 0
                                               AND "Total" >= 0
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_Subtotal"
                                       CHECK (
                                           "Subtotal" =
                                           round("Cantidad" * "PrecioUnitario", 2)
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_ImporteDescuento"
                                       CHECK (
                                           "ImporteDescuento" =
                                           round(
                                                   "Subtotal" * "DescuentoPorcentaje" / 100,
                                                   2
                                           )
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_BaseImponible"
                                       CHECK (
                                           "BaseImponible" =
                                           "Subtotal" - "ImporteDescuento"
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_ImporteImpuesto"
                                       CHECK (
                                           "ImporteImpuesto" =
                                           round(
                                                   "BaseImponible" * "PorcentajeImpuesto" / 100,
                                                   2
                                           )
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_Total"
                                       CHECK (
                                           "Total" =
                                           "BaseImponible" + "ImporteImpuesto"
                                           ),

                                   CONSTRAINT "CK_DetallesFactura_ImpuestoOpcional"
                                       CHECK (
                                           "ImpuestoId" IS NOT NULL
                                               OR (
                                               "PorcentajeImpuesto" = 0
                                                   AND "ImporteImpuesto" = 0
                                               )
                                           )
);

CREATE INDEX "IX_DetallesFactura_FacturaId"
    ON "DetallesFactura" ("FacturaId");

CREATE INDEX "IX_DetallesFactura_ProductoId"
    ON "DetallesFactura" ("ProductoId");

CREATE INDEX "IX_DetallesFactura_ImpuestoId"
    ON "DetallesFactura" ("ImpuestoId");
